data.query:
query Query($where: ResourceProcessListWhereInput, $orderBy: [ResourceProcessListOrderByInput!], $first: Int, $after: String) {
  resourceProcessList(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        quantity
        requireSerial
        workOrderOnly
        productStrategyProcessId
        resourceId
        resource {
          id
          quantity
        }
        workOrderProcess {
          workOrderProcessDistributions {
            edges {
              node {
          id scheduledStartAt scheduledFinishAt
      }
      }
    }
    }
      }
    }
  }
}

query Query($where: WorkOrderProcessDistributionWhereInput, $orderBy: [WorkOrderProcessDistributionOrderByInput!], $first: Int, $after: String) {
  workOrderProcessDistribution(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        scheduledFinishAt
        scheduledStartAt
        workOrderProcess {
          productStrategyProcessId
        }
      }
    }
  }
}

data.transform:
function res(resources) {
    const cal = []
    const total = resources[0].total
    for (let i = 0; i < resources.length; i++) {
        for (let ii = 0; ii < resources[i].dists.length; ii++) {
            cal.push({
                "quantity": resources[i].quantity,
                "start": resources[i].dists[ii].scheduledStartAt,
                "end": resources[i].dists[ii].scheduledFinishAt,
            })
        }
    }
    return {
        "total": total,
        "cal": cal
    }
}

return res($)

